// Analisar contexto da mensagem para atendimento inicial
const contexto = JSON.parse($json.contexto);
const mensagem = contexto.mensagem_original.toLowerCase();
const dadosEntrada = contexto.dados_entrada;
const canal = contexto.canal;

// Detectar tipo de interesse principal
let tipoInteresse = 'indefinido';
let urgencia = 'normal';
let qualificacao = 0;

// Palavras-chave para detecção de intenção
const intencoes = {
  compra: ['comprar', 'adquirir', 'financiar', 'parcelar', 'próprio', 'casa própria', 'apartamento próprio'],
  venda: ['vender', 'comercializar', 'anunciar', 'proprietário', 'tenho um', 'meu imóvel'],
  aluguel: ['alugar', 'locar', 'inquilino', 'locação', 'arrendar', 'para morar'],
  investimento: ['investir', 'investimento', 'renda', 'rentabilidade', 'aplicar dinheiro'],
  informacao: ['informação', 'dúvida', 'pergunta', 'como funciona', 'gostaria de saber']
};

// Detectar intenção principal
for (const [tipo, palavras] of Object.entries(intencoes)) {
  if (palavras.some(palavra => mensagem.includes(palavra))) {
    tipoInteresse = tipo;
    break;
  }
}

// Detectar urgência
const palavrasUrgencia = ['urgente', 'rápido', 'hoje', 'agora', 'preciso logo', 'emergência'];
if (palavrasUrgencia.some(palavra => mensagem.includes(palavra))) {
  urgencia = 'alta';
}

// Calcular score inicial de qualificação
qualificacao += tipoInteresse !== 'indefinido' ? 20 : 0;
qualificacao += dadosEntrada.telefone ? 15 : 0;
qualificacao += dadosEntrada.email ? 10 : 0;
qualificacao += mensagem.length > 50 ? 10 : 5; // Mensagem detalhada
qualificacao += canal === 'whatsapp' ? 10 : 5; // WhatsApp indica mais engajamento

// Detectar informações específicas na mensagem
const infoEspecificas = {
  valor: /r\$\s*([\d.,]+)|([\d.,]+)\s*mil|([\d.,]+)\s*reais/i.test(mensagem),
  localizacao: /(bairro|região|zona|próximo|perto)/i.test(mensagem),
  quartos: /(quarto|dormitório|suíte)/i.test(mensagem),
  tipo_imovel: /(casa|apartamento|sobrado|cobertura|terreno|comercial)/i.test(mensagem)
};

// Bonus por informações específicas
Object.values(infoEspecificas).forEach(tem => {
  if (tem) qualificacao += 5;
});

// Extrair valores mencionados
const valorMatch = mensagem.match(/r\$\s*([\d.,]+)|([\d.,]+)\s*mil/i);
let valorEstimado = null;
if (valorMatch) {
  const valor = valorMatch[1] || valorMatch[2];
  valorEstimado = parseFloat(valor.replace(/[.,]/g, '')) * (valorMatch[0].includes('mil') ? 1000 : 1);
}

// Extrair localização mencionada
const localizacaoMatch = mensagem.match(/(\w+\s*(?:zona|bairro|região)|\w+(?:\s+\w+){0,2}(?=\s*(?:sp|são paulo|rj|rio)))/i);
const localizacaoMencionada = localizacaoMatch ? localizacaoMatch[0] : null;

return {
  json: {
    contexto_original: contexto,
    analise: {
      tipo_interesse: tipoInteresse,
      urgencia: urgencia,
      score_qualificacao: Math.min(100, qualificacao),
      valor_estimado: valorEstimado,
      localizacao_mencionada: localizacaoMencionada,
      info_especificas: infoEspecificas,
      canal: canal
    },
    dados_entrada: dadosEntrada
  }
};

// Gerar resposta personalizada de atendimento inicial
const analise = $('Analisar Contexto e Intenção').first().json.analise;
const dadosEntrada = $('Analisar Contexto e Intenção').first().json.dados_entrada;
const clienteExistente = $('Buscar Cliente Existente').first().json;
const canal = analise.canal;

// Determinar se é cliente novo ou existente
const isNovoCliente = !clienteExistente.id;
const nomeCliente = clienteExistente.nome || dadosEntrada.nome || 'Cliente';
const primeiroNome = nomeCliente.split(' ')[0];

// Templates de resposta por tipo de interesse e canal
const templates = {
  whatsapp: {
    compra: {
      novo: `Olá! 😊

Que bom ter você aqui! Vi que você tem interesse em comprar um imóvel.

Para te ajudar melhor, me conta:

🏠 Que tipo de imóvel você procura?
📍 Em qual região?
💰 Qual sua faixa de investimento?

Vou buscar as melhores opções para você! 🎯`,
      existente: `Oi ${primeiroNome}! 👋

Bom te ver por aqui novamente!

Vi que você está interessado em comprar. Que tal darmos uma olhada nas novidades que chegaram?

Tenho algumas opções incríveis que podem te interessar! 🏠✨`
    },
    venda: {
      novo: `Olá! 😊

Perfeito! Você quer vender seu imóvel, certo?

Vou te ajudar a conseguir o melhor negócio!

📋 Me conta mais sobre seu imóvel:
🏠 Tipo (casa, apartamento, etc.)
📍 Localização
📐 Tamanho aproximado

Vamos fazer uma avaliação gratuita! 💰`,
      existente: `Oi ${primeiroNome}! 😊

Que bom saber que você quer vender!

Com base no seu perfil, posso fazer uma avaliação bem precisa do seu imóvel.

Quer agendar uma visita para avaliarmos? 📅`
    },
    aluguel: {
      novo: `Olá! 😊

Entendi que você procura um imóvel para alugar!

Vou te ajudar a encontrar o lugar perfeito! 🏠

📝 Me fala:
📍 Qual região você prefere?
💰 Qual seu orçamento mensal?
👥 Quantas pessoas vão morar?

Tenho várias opções disponíveis! 🔑`,
      existente: `Oi ${primeiroNome}! 👋

Voltou para procurar aluguel? Ótimo!

Tenho novidades que podem te interessar na região que você gosta!

Quer ver as opções disponíveis? 🏠`
    },
    investimento: {
      novo: `Olá! 😊

Excelente escolha investir em imóveis! 📈

Vou te mostrar as melhores oportunidades do mercado!

💼 Me conta:
💰 Qual valor você quer investir?
🎯 Prefere renda ou valorização?
📍 Alguma região específica?

Vamos encontrar o investimento perfeito! 💎`,
      existente: `Oi ${primeiroNome}! 💼

Sempre bom ver um investidor esperto!

Tenho algumas oportunidades exclusivas que podem te interessar muito!

Quer dar uma olhada? 📊`
    },
    indefinido: {
      novo: `Olá! 😊

Seja bem-vindo(a)! Como posso te ajudar hoje?

🏠 Está procurando imóvel para:
• Comprar
• Vender
• Alugar
• Investir

Me conta qual sua necessidade que vou te ajudar da melhor forma! 💪`,
      existente: `Oi ${primeiroNome}! 👋

Bom te ver novamente!

Em que posso te ajudar hoje? Tenho várias novidades desde nossa última conversa! 😊`
    }
  },

  email: {
    compra: {
      novo: `Olá!

Obrigado por entrar em contato. Vi que você tem interesse em comprar um imóvel.

Para oferecer as melhores opções, gostaria de saber:

• Tipo de imóvel desejado
• Região de preferência
• Faixa de investimento

Ficarei feliz em ajudar você a encontrar o imóvel ideal!`,
      existente: `Olá ${primeiroNome}!

Que bom receber seu contato novamente!

Vi que você está interessado em comprar. Tenho algumas novidades que podem te interessar muito.

Gostaria de agendar uma conversa para apresentar as opções?`
    },
    venda: {
      novo: `Olá!

Perfeito! Você quer vender seu imóvel.

Para fazer uma avaliação precisa, preciso de algumas informações:

• Tipo do imóvel
• Localização
• Características principais

Podemos agendar uma visita para avaliação gratuita?`,
      existente: `Olá ${primeiroNome}!

Que bom saber que você quer vender seu imóvel!

Com base no seu histórico, posso fazer uma avaliação bem direcionada.

Que tal agendarmos uma visita?`
    },
    aluguel: {
      novo: `Olá!

Entendi que você procura um imóvel para alugar.

Para encontrar a melhor opção, me informe:

• Região de preferência
• Orçamento mensal
• Número de pessoas

Tenho várias opções disponíveis que podem te interessar!`,
      existente: `Olá ${primeiroNome}!

Bom saber que você está procurando aluguel novamente!

Tenho algumas opções novas na região que você costuma procurar.

Gostaria de ver as disponibilidades?`
    },
    indefinido: {
      novo: `Olá!

Obrigado por entrar em contato.

Como posso ajudá-lo hoje? Trabalho com:

• Compra de imóveis
• Venda de imóveis
• Locação
• Investimentos

Fique à vontade para me contar sua necessidade.`,
      existente: `Olá ${primeiroNome}!

Bom receber seu contato novamente!

Em que posso ajudá-lo hoje? Tenho várias novidades desde nossa última conversa.`
    }
  }
};

// Selecionar template apropriado
const tipoCliente = isNovoCliente ? 'novo' : 'existente';
const tipoInteresse = analise.tipo_interesse;

let resposta = '';
if (templates[canal] && templates[canal][tipoInteresse] && templates[canal][tipoInteresse][tipoCliente]) {
  resposta = templates[canal][tipoInteresse][tipoCliente];
} else if (templates[canal] && templates[canal]['indefinido']) {
  resposta = templates[canal]['indefinido'][tipoCliente];
} else {
  // Fallback
  resposta = isNovoCliente ? 
    'Olá! Obrigado por entrar em contato. Como posso ajudá-lo hoje?' :
    `Olá ${primeiroNome}! Bom falar com você novamente. Em que posso ajudar?`;
}

// Determinar próximas ações
let proximasAcoes = [];
let requerHitl = false;

// Verificar se precisa de intervenção humana
if (analise.urgencia === 'alta') {
  requerHitl = true;
  proximasAcoes.push('escalar_urgencia');
}

if (analise.score_qualificacao >= 70) {
  proximasAcoes.push('agendar_visita');
} else if (analise.score_qualificacao >= 40) {
  proximasAcoes.push('qualificar_mais');
} else {
  proximasAcoes.push('nurturing');
}

if (analise.tipo_interesse === 'venda') {
  proximasAcoes.push('agendar_avaliacao');
}

return {
  json: {
    resposta: resposta,
    tipo_interesse: analise.tipo_interesse,
    score_qualificacao: analise.score_qualificacao,
    urgencia: analise.urgencia,
    is_novo_cliente: isNovoCliente,
    proximas_acoes: proximasAcoes,
    requer_hitl: requerHitl,
    dados_contexto: {
      analise: analise,
      cliente: clienteExistente,
      dados_entrada: dadosEntrada
    }
  }
};
